def lexicographically_smallest_longest_line(s, k):
    lines = [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)]
    for _ in range(k):
        n = len(lines)
        new_lines = []
        for i in range(n):
            if lines[i] != "":
                new_line = ""
                j = 0
                while j < len(lines[i]):
                    if lines[i][len(lines[i]) - j - 1] == "0":
                        new_line += "0"
                        if len(lines[i]) - j - 1 < k - 1:
                            new_line += lines[i]
                        if j > 0:
                            new_lines.append(new_line)
                        new_line = lines[i][j:]
                        j = 0
                    else:
                        new_line += lines[i][j]
                        j += 1
                del new_lines[n - i - 1]
            new_lines.append(new_line)
        lines = new_lines
    return "".join(lines)

