    def bellman_ford(self, start):
        distance = [float('inf')] * self.n
        distance[start - 1] = 0
        prev = [None] * self.n
        for _ in range(self.n - 1):
            for u in range(self.n):
                for v in self.adj[u]:
                    distance[v] = min(distance[v], distance[u] + self.weights[v])
            for v in range(self.n):
                if distance[v] == float('inf'):
                    distance[v] == 0
                    prev[v] = 0
        for i in range(self.n):
            distance[i] = distance[i] * pow(2, self.weights[i] // max_value, max_value) + (self.weights[i] % max_value)
            prev[i] += distance[i] * comb(self.n - self.indegree[i], self.indegree[i], exact=True) ^ self.n % max_value
            self.indegree[i] += 1
