from collections import deque

def check_strongly_connected(adj_list, sources, sinks):
    def dfs(vertex, visited):
        visited[vertex] = True
        for neighbor in adj_list[vertex]:
            if not visited[neighbor]:
                dfs(neighbor, visited)
        return vertex

    def canonical_vertex(source):
        while adj_list[source][-1] == source:
            source = adj_list[source][-1]
        return source

    sources.reverse()
    sinks.reverse()
    visited_sources = []
    visited_sinks = []
    common_sources = deque()
    common_sinks = deque()

    for i in range(len(sources)):
        while visited_sources and sources[visited_sources[0]] > sinks[i]:
            pop_source = visited_sources.popleft()
            adj_list[sources[pop_source]].pop()
            visited_sources.extend([sources.pop(p) for p in range(len(sources)) if sources[p] == pop_source])
        while visited_sinks and sinks[visited_sinks[0]] > sources[i]:
            pop_sink = visited_sinks.popleft()
            adj_list[sinks[pop_sink]].pop()
            visited_sinks.extend([sinks.pop(p) for p in range(len(sinks)) if sinks[p] == pop_sink])

        vertex = dfs(sources[i], visited_sources + [sources[i]])
        if adj_list[vertex][-1] == vertex and adj_list[vertex][0] == vertex:
            common_sources.append(vertex)
        else:
            adj_list[vertex].remove(adj_list[vertex][-1])
        vertex = dfs(sinks[i], visited_sinks + [sinks[i]])
        if adj_list[vertex][-1] == vertex and adj_list[vertex][0] == vertex:
            common_sinks.append(vertex)
        else:
            adj_list[vertex].remove(adj_list[vertex][0])

        if adj_list[vertex][-1] != vertex and adj_list[vertex][0] == vertex:
            common_sinks.append(vertex)
        else:
            adj_list[vertex].remove(adj_list[vertex][-1])

    adj_list.pop(common_sources[0])
    adj_list.pop(common_sinks[0])

    for vertex in list(adj_list.keys()):
        if len(adj_list[vertex]) != 1 and adj_list[vertex][0] == vertex:
            adj_list[vertex].remove(vertex)
            adj_list[vertex].append(adj_list[vertex][0])
            adj_list[vertex].remove(adj_list[vertex][0])

    target = canonical_vertex(common_sources[0])
    starting_source = sink_node = target
    source = sink_node = target
    for vertex in adj_list[target]:
        if vertex < starting_source:
            starting_source = min(source, vertex)
        elif vertex > sink_node:
            sink_node = max(sink_node, vertex)

    if starting_source != source or sink_node != sink_node:
        print("NO")
        return

    target_final = canonical_vertex(common_sinks[target_final])
    starting_sink = sink_node = target_final
    source = sink_node = target_final
    for vertex in adj_list[target_final]:
        if vertex < starting_sink:
