def min_fire_balls(n, a, b, healths):
    # Map to keep track of archers' health and powers
    healths_per_archer = [0] * n
    for i in range(n):
        healths_per_archer[i] = healths[i]

    # Priority queue to minimize max health left
    min_heap = []
    for i in range(1, n):
        max_left, min_right = i - b, i + b
        if max_left > 0 and min_right < n and healths_per_archer[max_left - 1] >= min_right > 0:
            if healths_per_archer[i] >= min_right > 0:
                min_heap.append((min_right, i))
        if max_left > 0 and healths_per_archer[max_left - 1] < healths_per_archer[i]:
            min_heap.append((healths_per_archer[i], i))
        if min_right < n and healths_per_archer[min_right + 1] >= max_left > 0:
            if healths_per_archer[min_right + 1] >= max_left > 0:
                min_heap.append((max_left, min_right + 1))
        if min_right < n and min_right + 1 < len(healths_per_archer) and healths_per_archer[max_left - 1] < healths_per_archer[min_right + 1]:
            min_heap.append((min_right + 1, min_right + 2))

    min_heap.sort()
    used_indices = set()

    def dfs(current_index, current_health):
        if current_health < 0:
            return 0

        max_health = healths_per_archer[current_index]
        if max_health >= current_health and current_index not in used_indices:
            used_indices.add(current_index)
            fire_names = [current_index]

        for i in range(1, a):
            if len(min_heap) <= 0:
                return float('inf')
            current_health_used, current_index_used = min_heap.pop()
            next_max_health = max(max_health - b - a + 1 - i, 0)

            if current_index_used not in used_indices and next_max_health >= current_health - i:
                used_indices.add(current_index_used)
                fire_names.append(current_index_used)

        if a != len(min_heap):
            fire_names.append(current_index)
        fire_names.sort()

        return 1 + sum(dfs(i, current_health - a) for i in fire_names)

    return dfs(1, healths_per_archer[1])

