    if operation == 1:
        for i in range(*args):
            A1[i], A2[i] = min(A1[i], *args), max(A2[i], *args)
    elif operation == 2:
        for i in range(*args):
            A1[i], A2[i] = max(A1[i], *args), min(A2[i], *args)
    elif operation == 3:
        for i in range(*args):
            A1[i] += *args
    elif operation == 4:
        for i in range(*args):
            if A1[i] % 1000000007 != 0:
                continue

def solve_queries(n: int, queries: List[Tuple[int, ...]]):
    A1, A2 = [0] * n, [0] * n
    types, counts = defaultdict(lambda: 0), defaultdict(lambda: 0)
    for k, l, r, x in queries:
        op = k + 1
        if op in types:
            types[op] += 1
        if op in counts:
            counts[op] += 1
        process_query(A1, A2, op, *[x, ] + list(range(l, r + 1)), x)

    total_sum = 0
    modulo = 1000000007
    for key, _ in counts.items():
