import sys
from collections import deque

def find_bst(children, node):
    frontier = deque([node])
    parent = {node}

    while frontier:
        curr = frontier.popleft()
        for neighbor in children[curr]:
            if neighbor not in parent:
                parent.add(neighbor)
                frontier.append(neighbor)

    return parent

def process_bsts(parents, bst):
    bst_size = len(bst)
    connections = 0
    for i in range(1, len(parents)):
        if len(parents[i]) == bst_size:
            return connections + 1
        else:
            connections += 1

    return connections

def find_good_cutting_point(parents, edges, N):
    tree_size = N

    while not all(len(parents[i]) == tree_size - 1 for i in range(N)):
        parent = find_bst(edges, 0)
        tree_size -= 1
        if 0 in parents:
            parents.remove(0)

    for i in range(N):
        if len(parents[i]) < tree_size - 1:
            bst = parents[i]
            return 0 if find_bst(edges, 0) != 0 else process_bsts(parents, bst)

    return 0 if find_bst(edges, 0) != 0 else process_bsts(parents, find_bst(edges, 0))

def solve():
    N = int(input())
    edges = [tuple(map(int, input().split())) for _ in range(N - 1)]

    if find_good_cutting_point([set() for _ in range(N)], edges, N) >= 0:
        print(0)
    else:
        print(-1)

if __name__ == "__main__":
    sys.setrecursionlimit(10**7)
    solve()
