def smallest_result(s, k):
    from functools import lru_cache

    @lru_cache(None)
    def min_result(index, remaining_parts):
        if remaining_parts == 1:
            return s[index:]
        result = s[index:]
        for i in range(index, len(s)-remaining_parts+1):
            previous = result
            result += s[i]
            for j in range(i, i-remaining_parts+1, -1):
                result = min(result, previous[:-(j-i)] + previous[:j-i])
            previous = result
        return result

    return min_result(0, k)

# Example usage:
