from typing import List

def fireball_parry(h: List[int], a: int, b: int) -> List[int]:
    n = len(h)
    dp = [[10 ** 10] * n for _ in range(n)]
    dp[0][0] = h[0]
    for i in range(1, n):
        for j in range(i, -1, -1):
            dp[i][j] = h[i] + max(dp[i-1][k] for k in range(max(0, j - b), j))

    cost = [dp[-1][j] for j in range(n)]
    used = [1] * n

    def backtrack(i: int) -> int:
        if i < 2:
            return cost[i-1]
        if used[i]:
            return backtrack(i-1)
        total_cost = cost[i-1]
        for k in range(i-2, max(0, i-2-b), -1):
            if used[k]:
                continue
            total_cost = min(total_cost, cost[i-1] + backtrack(k))
        return cost[i-1] + backtrack(i-2)

    fireballs = backtrack(n - 1 - 1) + 1
    return fireballs

