    edge_combinations = set()
    for comb in combinations(edges, 2):
        for e1, e2 in comb:
            if e1[0] < e2[0]:
                edge_combinations.add(((e1[0], e2[0]), (e1[1], e2[1])))
            else:
                edge_combinations.add(((e1[0], e2[1]), (e1[1], e2[0])))
    return edge_combinations

def compute_maximum_unconnected_trees(root, good_cutting_points, tree_nodes):
