def evaluate_expression(expression: str) -> int:
    import operator
    from itertools import zip_longest
    ops = {'+': operator.add, '*': operator.mul}

    def evaluate(tokens):
        stack = []
        tokens = iter(tokens)
        while next(tokens) != '+':
            token = next(tokens)
            if token == '*':
                next(tokens)
                stack[-1] *= next(tokens)
            else:
                token, next_token = next(tokens), next(tokens)
                op = ops[token]
                stack.append(op(next(stack.pop()), next(stack.pop())))
        result = next(stack)
        return eval(result)

