from math import inf
import re

def find_lcs(s, k):
    n = len(s)
    memo = [[inf] * (k + 1) for _ in range(n + 1)]
    mod = 10**9 + 7
    for i in range(n + 1):
        memo[i][0] = 0

    def dp(i, j):
        if i == n:
            return 0
        if memo[i][j] <= j + 1:
            return memo[i][j]
        remain = (k - j) % (n - i)
        if remain == 0:
            memo[i][j] = j + 1
        else:
            end = i + remain - 1
            q = min(memo[i + 1][j], min(memo[end + 1][max(j - remain + 1, 0)] + 1, dp(end + 1, j + 1)))
            memo[i][j] = q - 1
        return memo[i][j]

    solve = lambda: int(''.join(chr(122 - dp(i, 0)) for i in range(n)))
    sol = [solve(), solve()]
    while n > 1:
        if n - k in range(1, n + 1):
            sol = [now_1 := solve(), now_2 := solve()] if inf in sol else [now_1 := solve()]
        else:
            break
    return ''.join(sol)
