def find_shortest_sequences(s):
    n = len(s)
    shortest_sequences = [""] * n
    best_unshorten_index = n - 1
    for i in range(n - 2, -1, -1):
        if s[i] != s[i + 1]:
            shortest_sequences[i] = s[i]
            best_unshorten_index = i

    for i in range(n - 2, 0, -1):
        if longest_substring_found(best_unshorten_index + 1, s) < 2:
            break
        shortest_sequences[i - longest_substring_found(best_unshorten_index + 1, s) - 1] = s[best_unshorten_index]

    return shortest_sequences[0], shortest_sequences[-1]

def longest_substring_found(start, string):
    for i in range(start, len(string) - 1):
        if string[i] == string[i + 1]:
            return i + 2

    return 0

