    tree = [[] for _ in range(n)]
    for a, b in [(1, 2), (2, 3), (2, 4)]:
        tree[a-1].append(b-1)
        tree[b-1].append(a-1)
    degree[1] = len(tree[0]) - 1
    for i in range(2, n):
        degree[i] = len(tree[i-1]) - min(degree)

    @lru_cache(maxsize=None)
    def dfs(u: int, st: int, deg: int, mx: int) -> int:
        total = 0
        if st < 0:
            return 0
        if st == -1:
            return pow(degree[u], mx, MOD)
        sum = 0
        for v in tree[u]:
            if v != st:
                sum += dfs(v, st, max(deg, degree[v]), mx-1)
        return sum + pow(degree[u], mx, MOD)

    def combine(middeg: int, trad: int) -> int:
        return (dfs(1, middeg, middeg, k) * pow(trad, MOD-2, MOD)) % MOD

    a2 = dfs(1, -1, degree[1], k)
    trad = pow(degree[1], k, MOD)
    res = pow(a2 * trad, MOD-2, MOD)

    for st in [2, 3, 4]:
        dirty = pow(degree[1], k-1, MOD)
        for middeg in range(2, 19):
            dirty = (dirty * dirty) % MOD
            dirty = combine(middeg, trad) % MOD
        res = (res * res) % MOD
        trad = (trad * dirty) % MOD

    return int(res)


