def is_strongly_connected_by_finding_sinks(n, m, edges, sources, sinks):
    # Set to store visited vertices and marked vertices to detect self-loops
    visited = [False] * (n + 1)
    marked = [False] * (n + 1)

    def is_acyclic():
        # Perform topological sort to detect acyclicity
        topo_order = []
        stack = [s for s in sources if not marked[s]]
        while stack:
            current = stack.pop()
            topo_order.append(current)
            for neighbor in edges[current]:
                if edge[neighbor][current]:
                    if marked[neighbor]:
                        # If there's a self-loop, return False
                        return False
                    else:
                        marked[neighbor] = True
                        stack.append(neighbor)
                else:
                    edge[current][neighbor] = edge[neighbor][current] = True

        # Check if all vertices are in the topo_order
        for vertex in topo_order:
            for neighbor in range(1, n + 1):
                if visited[vertex] or edge[vertex][neighbor]:
                    # If a vertex or an edge from vertex to another vertex exists, return False
                    return False
        return True

    # Return 'YES' if graph becomes strongly connected for any sources and sinks
    return 'YES' if is_acyclic() else 'NO'
